import React, { useState } from 'react';
import Sidebar from './Sidebar';
import logo from '../logo.png'; // ⚠️ logo path එක නිවැරදිද බලන්න

export default function StudentDashboard({ userName, handleLogout }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  // Student Subpages
  const renderSubPage = () => {
    switch (currentSubPage) {
      case 'Overview':
        return <div><h2>Student Overview</h2></div>;
      case 'Study Materials':
        return <div><h2>Study Materials</h2></div>;
      case 'Lesson Activities':
        return <div><h2>Lesson Activities</h2></div>;
      case 'Exams & Quizzes':
        return <div><h2>Exams & Quizzes</h2></div>;
      case 'Class Timetable':
        return <div><h2>Class Timetable</h2></div>;
      case 'Feedback':
        return <div><h2>Feedback</h2></div>;
      case 'Settings':
        return <div><h2>Settings</h2></div>;
      default:
        return <div><h2>Student Overview</h2></div>;
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', backgroundColor: '#f1f5f9', overflow: 'hidden' }}>
      
      {/* 🟢 Admin Layout එකටම සමාන Top Header එක */}
      <header style={styles.header}>
        <img src={logo} alt="Logo" style={{ height: '58px', width: 'auto' }} /> 
        <div style={styles.welcomeText}>
          Welcome, {userName || 'Student'} 🎓
        </div>
      </header>

      {/* Main Layout Splitter */}
      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        <Sidebar 
          currentSubPage={currentSubPage} 
          setCurrentSubPage={setCurrentSubPage} 
          onLogoutClick={handleLogout} 
          role="student"
        />

        <div style={{ flex: 1, padding: '24px', overflowY: 'auto', height: '100%' }}>
          {renderSubPage()}
        </div>
      </div>
    </div>
  );
}

const styles = {
  header: {
    height: '80px',
    backgroundColor: '#ffffff',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: '0 30px',
    borderBottom: '1px solid #e2e8f0',
    zIndex: 10,
    boxShadow: '0 2px 8px rgba(0,0,0,0.03)'
  },
  welcomeText: {
    fontSize: '18px',
    fontWeight: '700',
    color: '#1e293b'
  }
};
